type TickerProps = { items: string[]; reducedMotion: boolean };

export function Ticker({ items, reducedMotion }: TickerProps) {
  const content = items.join('  ·  ');
  return <div className={`ticker${reducedMotion ? ' ticker-static' : ''}`} aria-label={content}><div className="ticker-track">{[0, 1].map((copy) => <span key={copy} aria-hidden={copy === 1}>{content}  ·  </span>)}</div></div>;
}
