'use client';

import { type PropsWithChildren, useRef } from 'react';

type SpotlightCardProps = PropsWithChildren<{ className?: string; spotlightColor: string; disabled?: boolean }>;

/** Adapted from React Bits' dependency-free Spotlight Card component. */
export function SpotlightCard({ children, className = '', spotlightColor, disabled = false }: SpotlightCardProps) {
  const cardRef = useRef<HTMLDivElement>(null);
  const handlePointerMove: React.PointerEventHandler<HTMLDivElement> = (event) => {
    if (disabled || event.pointerType !== 'mouse' || !cardRef.current) return;
    const rect = cardRef.current.getBoundingClientRect();
    cardRef.current.style.setProperty('--mouse-x', `${event.clientX - rect.left}px`);
    cardRef.current.style.setProperty('--mouse-y', `${event.clientY - rect.top}px`);
  };
  return <div ref={cardRef} className={`spotlight-card ${className}`} style={{ '--spotlight-color': spotlightColor } as React.CSSProperties} onPointerMove={handlePointerMove}>{children}</div>;
}
