'use client';

import { useEffect, useRef } from 'react';

type ShapeGridProps = { color: string; reducedMotion: boolean };

/** Adapted from React Bits' Shape Grid; kept decorative and non-interactive. */
export function ShapeGrid({ color, reducedMotion }: ShapeGridProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const context = canvas?.getContext('2d');
    if (!canvas || !context) return;

    let startedAt = 0;
    let animationFrame = 0;
    let isQueued = false;
    let isVisible = true;
    const pointer = { x: 0.65, y: 0.4 };
    const cellSize = 46;
    const resize = () => {
      const bounds = canvas.getBoundingClientRect();
      const pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(bounds.width * pixelRatio);
      canvas.height = Math.round(bounds.height * pixelRatio);
      context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
    };
    const draw = (timestamp = 0) => {
      if (!startedAt) startedAt = timestamp;
      const { width, height } = canvas.getBoundingClientRect();
      context.clearRect(0, 0, width, height);
      context.strokeStyle = color;
      context.lineWidth = 1;
      const elapsed = reducedMotion ? 0 : (timestamp - startedAt) / 1000;
      const offset = (elapsed * 20) % cellSize;
      for (let x = -cellSize; x < width + cellSize; x += cellSize) {
        for (let y = -cellSize; y < height + cellSize; y += cellSize) {
          const diagonal = (x + y + offset * 6) / 150;
          const pulse = reducedMotion ? 0 : (Math.sin(diagonal) + 1) / 2;
          context.globalAlpha = 0.36 + pulse * 0.64;
          context.strokeRect(x + offset, y + offset, cellSize, cellSize);
        }
      }
      if (!reducedMotion && isVisible) {
        const glowX = pointer.x * width;
        const glowY = pointer.y * height;
        const glow = context.createRadialGradient(glowX, glowY, 0, glowX, glowY, Math.max(width, height) * 0.32);
        glow.addColorStop(0, 'rgba(255, 255, 255, 0.13)');
        glow.addColorStop(1, 'rgba(255, 255, 255, 0)');
        context.globalAlpha = 1;
        context.fillStyle = glow;
        context.fillRect(0, 0, width, height);
        requestDraw();
      }
    };
    const requestDraw = () => {
      if (isQueued || reducedMotion || !isVisible) return;
      isQueued = true;
      animationFrame = window.requestAnimationFrame((timestamp) => {
        isQueued = false;
        draw(timestamp);
      });
    };
    const resizeObserver = new ResizeObserver(() => { resize(); draw(performance.now()); });
    const visibilityObserver = new IntersectionObserver(([entry]) => {
      isVisible = entry.isIntersecting;
      if (isVisible) requestDraw();
    });
    const handlePointerMove = (event: PointerEvent) => {
      const bounds = canvas.getBoundingClientRect();
      pointer.x = Math.min(1, Math.max(0, (event.clientX - bounds.left) / bounds.width));
      pointer.y = Math.min(1, Math.max(0, (event.clientY - bounds.top) / bounds.height));
    };
    resizeObserver.observe(canvas);
    visibilityObserver.observe(canvas);
    window.addEventListener('pointermove', handlePointerMove, { passive: true });
    resize();
    draw(performance.now());
    return () => {
      resizeObserver.disconnect();
      visibilityObserver.disconnect();
      window.removeEventListener('pointermove', handlePointerMove);
      window.cancelAnimationFrame(animationFrame);
    };
  }, [color, reducedMotion]);

  return <canvas ref={canvasRef} className="shape-grid" aria-hidden="true" />;
}
